import { createHash } from "node:crypto";
import { mkdir, stat, writeFile } from "node:fs/promises";
import { dirname } from "node:path";

export const sha256 = (value) =>
  createHash("sha256").update(value).digest("hex");

export function redactSecrets(secrets) {
  const values = [
    ...new Set(secrets.filter((value) => typeof value === "string" && value)),
  ].sort((a, b) => b.length - a.length);
  const text = (value) => {
    let result = String(value);
    for (const secret of values)
      result = result.split(secret).join("[REDACTED]");
    return result;
  };
  const value = (item) => {
    if (typeof item === "string") return text(item);
    if (Array.isArray(item)) return item.map(value);
    if (item && typeof item === "object")
      return Object.fromEntries(
        Object.entries(item).map(([key, entry]) => [
          key,
          /^(authorization|api_key)$/i.test(key) ? "[REDACTED]" : value(entry),
        ]),
      );
    return item;
  };
  return { text, value };
}

export async function privateDirectory(path) {
  await mkdir(path, { recursive: true, mode: 0o700 });
  const info = await stat(path);
  if (
    !info.isDirectory() ||
    (info.mode & 0o077) !== 0 ||
    info.uid !== process.getuid()
  )
    throw new Error(
      "Artifact directory must be private and owned by this user",
    );
}

export async function privateFile(path, value) {
  await privateDirectory(dirname(path));
  await writeFile(
    path,
    typeof value === "string" || Buffer.isBuffer(value)
      ? value
      : JSON.stringify(value, null, 2),
    { mode: 0o600 },
  );
}
